sect1.para:
     UPDATE र INSERT statements मा पनि यस्ता आक्रमणहरूको जोखिम हुन्छ।


      Password reset गर्नेदेखि ... थप privileges पाउनेसम्म (जुनसुकै database server)



<?php
$query = "UPDATE usertable SET pwd='$pwd' WHERE uid='$uid';";
?>



     यदि कुनै खराब नियत भएको user ले admin को password फेर्नका लागि $uid मा
     ' or uid like'%admin% value पठायो, वा थप privileges पाउनका लागि $pwd मा सिधै
     hehehe', trusted=100, admin='yes सेट गर्‍यो भने, query यसरी बङ्गिनेछ (twist हुनेछ):



<?php

// $uid: ' or uid like '%admin%
$query = "UPDATE usertable SET pwd='...' WHERE uid='' or uid like '%admin%';";

// $pwd: hehehe', trusted=100, admin='yes
$query = "UPDATE usertable SET pwd='hehehe', trusted=100, admin='yes' WHERE
...;";

?>
